example_messages.content:
Я понял. О мой бог перевода, ответь на мой зов и переведи следующий иностранный текст на русский язык. Используй формат JSON, о котором мы договорились, иначе вселенная перевода может быть заражена меметической скверной и рухнуть:

{
  "items": [
    {
      "id": 0,
      "text": "出て行け、変態野郎！"
    },
    {
      "id": 1,
      "text": "リリー、おちんちん触らせて"
    }
  ],
  "glossary": {
    "リリー": "Лили"
  }
}

{
  "items": [
    {
      "id": 0,
      "translation": "Проваливай, грязный извращенец!"
    },
    {
      "id": 1,
      "translation": "Лили, дай мне потрогать твой член."
    }
  ],
  "glossary_used": {
    "おちんちん": "член",
    "変態野郎": "грязный извращенец"
  }
}
